"""SQL shapes for the designer round-trip test: OK = must give identical results after SQL -> diagram -> SQL,
BAD = must be refused with a message (the SQL is kept and still runs)."""
OK = [
 ("simple", "SELECT s.shipment_gid, s.total_actual_cost FROM shipment s WHERE s.total_actual_cost > 20 ORDER BY s.total_actual_cost DESC", None),
 ("derived join (user story)", "SELECT s.shipment_gid, x.stops FROM shipment s INNER JOIN (SELECT shipment_gid, COUNT(*) AS stops FROM shipment_stop GROUP BY shipment_gid) x ON x.shipment_gid = s.shipment_gid", None),
 ("left join + extra ON", "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s LEFT JOIN shipment_refnum r ON r.shipment_gid = s.shipment_gid AND r.shipment_refnum_qual_gid = 'DEMO.BM'", None),
 ("comma join", "SELECT s.shipment_gid, l.location_name FROM shipment s, location l WHERE l.location_gid = s.source_location_gid AND s.total_actual_cost > 30", None),
 ("(+) outer join", "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s, shipment_refnum r WHERE r.shipment_gid(+) = s.shipment_gid AND r.shipment_refnum_qual_gid(+) = 'DEMO.PO'",
   "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s LEFT JOIN shipment_refnum r ON r.shipment_gid = s.shipment_gid AND r.shipment_refnum_qual_gid = 'DEMO.PO'"),
 ("(+) on first table → RIGHT", "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment_refnum r, shipment s WHERE r.shipment_gid(+) = s.shipment_gid",
   "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s LEFT JOIN shipment_refnum r ON r.shipment_gid = s.shipment_gid"),
 ("(+) plus WHERE on optional", "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s, shipment_refnum r WHERE r.shipment_gid(+) = s.shipment_gid AND r.shipment_refnum_value LIKE 'PO%'",
   "SELECT s.shipment_gid, r.shipment_refnum_value FROM shipment s LEFT JOIN shipment_refnum r ON r.shipment_gid = s.shipment_gid WHERE r.shipment_refnum_value LIKE 'PO%'"),
 ("group/having/order by position", "SELECT s.servprov_gid, COUNT(*) AS n, SUM(s.total_actual_cost) total FROM shipment s GROUP BY s.servprov_gid HAVING COUNT(*) > 2 ORDER BY 2 DESC", None),
 ("group by column not selected", "SELECT COUNT(*) AS n FROM shipment s GROUP BY s.dest_location_gid", None),
 ("top-level OR", "SELECT s.shipment_gid FROM shipment s WHERE s.total_actual_cost < 20 OR s.total_actual_cost > 60", None),
 ("between/in/like/is not null", "SELECT s.shipment_gid FROM shipment s WHERE s.total_actual_cost BETWEEN 10 AND 50 AND s.servprov_gid IN ('DEMO.SAPTCO','DEMO.NAQEL') AND s.shipment_gid LIKE 'DEMO.SH%' AND s.shipment_name IS NOT NULL", None),
 ("exists (correlated)", "SELECT s.shipment_gid FROM shipment s WHERE EXISTS (SELECT 1 FROM shipment_refnum r WHERE r.shipment_gid = s.shipment_gid)", None),
 ("self join + non-equality ON", "SELECT a.shipment_gid, b.shipment_gid AS other FROM shipment a JOIN shipment b ON b.source_location_gid = a.source_location_gid AND b.shipment_gid <> a.shipment_gid", None),
 ("right join", "SELECT l.location_gid, s.shipment_gid FROM shipment s RIGHT JOIN location l ON l.location_gid = s.source_location_gid WHERE l.location_xid IN ('RUH','DMM','JED')", None),
 ("full join", "SELECT l.location_gid, s.shipment_gid FROM shipment s FULL OUTER JOIN location l ON l.location_gid = s.dest_location_gid WHERE l.location_xid IN ('RUH','JED') OR l.location_xid IS NULL", None),
 ("distinct", "SELECT DISTINCT s.servprov_gid FROM shipment s", None),
 ("unaliased table", "SELECT shipment.shipment_gid FROM shipment WHERE shipment.total_actual_cost > 40", None),
 ("bare columns", "SELECT shipment_gid, total_actual_cost FROM shipment WHERE total_actual_cost > 40 ORDER BY total_actual_cost", None),
 ("expressions + case", "SELECT s.shipment_gid, NVL(s.shipment_name, '-') AS nm, CASE WHEN s.total_actual_cost > 40 THEN 'HIGH' ELSE 'LOW' END band FROM shipment s ORDER BY band, s.shipment_gid", None),
 ("expression filter", "SELECT s.shipment_gid FROM shipment s WHERE UPPER(s.shipment_xid) = 'SH0003'", None),
 ("left join derived w/ filter", "SELECT s.shipment_gid, st.cnt FROM shipment s LEFT JOIN (SELECT ss.shipment_gid, COUNT(*) cnt FROM shipment_status ss WHERE ss.status_value_gid = 'DEMO.ENROUTE_COMPLETED' GROUP BY ss.shipment_gid) st ON st.shipment_gid = s.shipment_gid ORDER BY s.shipment_gid", None),
 ("window function", "SELECT s.shipment_gid, ROW_NUMBER() OVER (PARTITION BY s.servprov_gid ORDER BY s.total_actual_cost DESC) AS rn FROM shipment s", None),
 ("aggregate expression", "SELECT s.servprov_gid, SUM(s.total_actual_cost) / COUNT(*) AS avg_cost FROM shipment s GROUP BY s.servprov_gid", None),
 ("order by alias + nulls", "SELECT s.shipment_name AS nm, s.shipment_gid FROM shipment s ORDER BY nm NULLS FIRST, 2 DESC", None),
 ("3-table comma join", "SELECT s.shipment_gid, ss.stop_num, l.location_name FROM shipment s, shipment_stop ss, location l WHERE ss.shipment_gid = s.shipment_gid AND l.location_gid = ss.location_gid AND ss.stop_num = 1", None),
 ("ON with OR", "SELECT s.shipment_gid, l.location_gid FROM shipment s JOIN location l ON (l.location_gid = s.source_location_gid OR l.location_gid = s.dest_location_gid)", None),
 ("cross join", "SELECT s.shipment_gid, sv.servprov_gid FROM shipment s CROSS JOIN servprov sv WHERE s.total_actual_cost > 60", None),
 ("derived first", "SELECT x.servprov_gid, x.n, sp.servprov_xid FROM (SELECT servprov_gid, COUNT(*) AS n FROM shipment GROUP BY servprov_gid) x JOIN servprov sp ON sp.servprov_gid = x.servprov_gid", None),
 ("hidden order column", "SELECT s.shipment_gid FROM shipment s ORDER BY s.total_actual_cost DESC", None),
 ("two filters one column", "SELECT s.shipment_gid FROM shipment s WHERE s.total_actual_cost >= 20 AND s.total_actual_cost <= 50", None),
 ("count distinct", "SELECT COUNT(DISTINCT s.servprov_gid) AS n FROM shipment s", None),
 ("scalar subquery", "SELECT s.shipment_gid, (SELECT COUNT(*) FROM shipment_stop ss WHERE ss.shipment_gid = s.shipment_gid) AS stops FROM shipment s", None),
 ("group by, no aggregate", "SELECT s.servprov_gid FROM shipment s GROUP BY s.servprov_gid", None),
 ("having with 2 conditions", "SELECT s.servprov_gid, COUNT(*) n FROM shipment s GROUP BY s.servprov_gid HAVING COUNT(*) > 1 AND MAX(s.total_actual_cost) > 40", None),
 ("quoted alias", 'SELECT s.shipment_gid AS "Shipment Id" FROM shipment s', None),
 ("comments + semicolon", "-- top\nSELECT /* x */ s.shipment_gid FROM shipment s -- end\n;", None),
 ("subquery without alias", "SELECT * FROM (SELECT servprov_gid FROM shipment WHERE total_actual_cost > 50)", None),
 ("cross-table WHERE between ANSI joins", "SELECT s.shipment_gid FROM shipment s JOIN shipment_stop ss ON ss.shipment_gid = s.shipment_gid JOIN location l ON l.location_gid = ss.location_gid WHERE l.location_gid = s.source_location_gid", None),
]
