 ("no FROM", "SELECT 1 AS x"),
 ("unbalanced", "SELECT s.shipment_gid FROM shipment s WHERE (s.total_actual_cost > 1"),
 ("two statements", "SELECT 1 AS a FROM dual; SELECT 2 AS b FROM dual"),
